import { asString, useSearchParam } from '../../url/useSearchParam';
import { ClaimForm } from '../claims/ClaimForm';
import { ClaimList } from '../claims/ClaimList';
import { countsLive, sumAmounts, useClaims } from '../claims/useClaims';
import { isOverdue } from '../claims/overdue';
import { claimDue, dueTotal, formatCents, showDue } from '../rates/due';
import { rateOn, useRates } from '../rates/useRates';
import { useFloor, useLatePct, useTerms } from '../settings/useSettings';
import { useSheetToday } from '../sheet/useSheetToday';
import { StatementButton } from '../statements/StatementButton';
import { HoldControl } from './HoldControl';
import { PatronControl } from './PatronControl';
import { QuickAdd } from './QuickAdd';
import { RetireControl } from './RetireControl';
import { ShowRetired, useShowRetired } from './ShowRetired';
import { gradeOn, usePeople, type Person } from './usePeople';

// Every person on the sheet in the order they were added, with their name, grade (the one in force on the sheet's today), claimed (the
// sum of their OPEN and SETTLED claims), due-total (the
// sum of their counting claims' already-rounded dues; n/a when their grade has no rate today and no settled or stated claim keeps a figure),
// whether they are retired and from when, whether they are on hold (a held person's OPEN claims count
// in neither their figures nor the sheet's totals; their SETTLED claims still do), their overdue count and
// patrons (names, sorted) and backing (their patrons' due-totals added up, skipping n/a; 0.00 with no patrons),
// their overdue count and overdue-total (how many of their counting claims are overdue, and the sum of those claims' dues with their late charges, n/a adding nothing), their statements (the statement button, how many were taken, the last one's due-total and date) and their claims; then the
// sheet's claimed-total, due-total (the people's due-totals added up, skipping n/a), overdue count and overdue-total. Retired
// people have no row unless "show retired" is on, but their claims keep counting in every total.
export function PeopleList() {
  const [sheet] = useSearchParam('sheet', asString);
  const [, setEditing] = useSearchParam('editPerson', asString);
  const people = usePeople(sheet);
  const [showRetired] = useShowRetired();
  const listed = showRetired ? people : people.filter((p) => !p.retired);
  const claims = useClaims(sheet);
  const rates = useRates(sheet);
  const today = useSheetToday(sheet);
  const floor = useFloor(sheet);
  const terms = useTerms(sheet);
  const late = { pct: useLatePct(sheet), terms, today };
  const heldOf = new Map(people.map((p) => [p.id, p.held]));
  const live = claims.filter((c) => heldOf.has(c.personId) && countsLive(c, heldOf.get(c.personId)!));
  // A claim is worked at the grade in force on its date; the row shows the one in force today.
  const totalOf = (person: Person) =>
    dueTotal(
      live.filter((c) => c.personId === person.id),
      (date) => rateOn(rates, gradeOn(person, date), date),
      rateOn(rates, gradeOn(person, today), today),
      floor,
      late,
    );
  const byId = new Map(people.map((p) => [p.id, p]));
  const backing = (p: (typeof people)[number]) =>
    formatCents(p.patronIds.reduce((sum, id) => {
      const patron = byId.get(id);
      const due = patron ? totalOf(patron) : null;
      return due === null ? sum : sum + due;
    }, 0n));

  const overdue = live.filter((c) => isOverdue(c, terms, today));
  const overdueOf = (personId: string) => overdue.filter((c) => c.personId === personId);
  const overdueTotal = (cs: typeof overdue) =>
    formatCents(cs.reduce((sum, c) => sum + (claimDue(c, rateOn(rates, gradeOn(byId.get(c.personId)!, c.date), c.date), floor, late) ?? 0n), 0n));
  return (
    <>
      <QuickAdd />
      <ShowRetired />
      <table data-testid="people">
        <thead>
          <tr>
            <th>Name</th>
            <th>Grade</th>
            <th>Claimed</th>
            <th>Due</th>
            <th>Patrons</th>
            <th>Backing</th>
            <th>Overdue</th>
            <th>Overdue due</th>
            <th />
            <th>Retired</th>
            <th>Retired from</th>
            <th>Hold</th>
            <th>Statements</th>
            <th>Last stated</th>
            <th>Stated on</th>
            <th>Claims</th>
          </tr>
        </thead>
        <tbody>
          {listed.map((p) => {
            const own = claims.filter((c) => c.personId === p.id);
            return (
              <tr key={p.id} data-testid={`person-row-${p.id}`}>
                <td data-testid="person-name">{p.name}</td>
                <td data-testid="person-grade">{gradeOn(p, today)}</td>
                <td data-testid="person-claimed">{sumAmounts(live.filter((c) => c.personId === p.id))}</td>
                <td data-testid="person-due-total">{showDue(totalOf(p))}</td>
                <td data-testid="person-patrons">{p.patrons.join(', ')}</td>
                <td data-testid="person-backing">{backing(p)}</td>
                <td data-testid="person-overdue-count">{overdueOf(p.id).length}</td>
                <td data-testid="person-overdue-total">{overdueTotal(overdueOf(p.id))}</td>
                <td>
                  <button type="button" data-testid={`person-edit-${p.id}`} onClick={() => setEditing(p.id)}>
                    Edit
                  </button>{' '}
                  <StatementButton personId={p.id} />{' '}
                  <RetireControl personId={p.id} />{' '}
                  <HoldControl personId={p.id} held={p.held} />{' '}
                  <PatronControl personId={p.id} people={people} />
                </td>
                <td data-testid="person-retired">{p.retired ? 'yes' : 'no'}</td>
                <td data-testid="person-retired-from">{p.retiredFrom}</td>
                <td data-testid="person-hold">{p.held ? 'yes' : 'no'}</td>
                <td data-testid="person-statement-count">{p.statementCount}</td>
                <td data-testid="person-stated-total">{p.statedTotal}</td>
                <td data-testid="person-statement-date">{p.statementDate}</td>
                <td>
                  <ClaimList claims={own} rateOn={(date) => rateOn(rates, gradeOn(p, date), date)} />
                  <ClaimForm personId={p.id} claims={own} />
                </td>
              </tr>
            );
          })}
        </tbody>
      </table>
      <p>
        Claimed total: <span data-testid="rollup-claimed-total">{sumAmounts(live)}</span>
      </p>
      <p>
        Due total: <span data-testid="rollup-due-total">{formatCents(people.reduce((sum, p) => {
          const due = totalOf(p);
          return due === null ? sum : sum + due;
        }, 0n))}</span>
      </p>
      <p>
        Overdue: <span data-testid="rollup-overdue-count">{overdue.length}</span>
      </p>
      <p>
        Overdue total: <span data-testid="rollup-overdue-total">{overdueTotal(overdue)}</span>
      </p>
    </>
  );
}
import { useState } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { postJson } from '../../api/http';
import { asString, useSearchParam } from '../../url/useSearchParam';
import { useSubmitOnce } from '../../query/useSubmitOnce';
import { countsLive, useClaims } from '../claims/useClaims';
import { gradeOn, usePeople } from '../people/usePeople';
import { claimDue, formatCents, toCents } from '../rates/due';
import { rateOn, useRates } from '../rates/useRates';
import { useFloor, useLatePct, useTerms } from '../settings/useSettings';
import { useSheetToday } from '../sheet/useSheetToday';
import { periodOf, periodsKey, usePeriods, type Period } from './usePeriods';

// The sheet's periods, each with its dates and due-total (the dues, late charges included, of the claims that count whose
// date falls in it, leaving out a held person's OPEN claims; a claim whose due is n/a adds nothing), and the form that adds one (a name not
// already on the sheet, a from-date on or before the to-date, not overlapping another period). A
// closed period shows the due-total fixed when it was closed, whatever the rates do later; a steward
// can reopen it, making its due-total live again.
export function PeriodPanel() {
  const [sheet] = useSearchParam('sheet', asString);
  const [user] = useSearchParam('user', asString);
  const periods = usePeriods(sheet);
  const people = usePeople(sheet);
  const claims = useClaims(sheet);
  const rates = useRates(sheet);
  const floor = useFloor(sheet);
  const late = { pct: useLatePct(sheet), terms: useTerms(sheet), today: useSheetToday(sheet) };
  const [name, setName] = useState('');
  const [from, setFrom] = useState('');
  const [to, setTo] = useState('');
  const queryClient = useQueryClient();
  const submitOnce = useSubmitOnce();
  const add = useMutation({
    mutationFn: (body: { name: string; from: string; to: string }) =>
      postJson<Period[]>(`/api/sheets/${encodeURIComponent(sheet)}/periods`, { ...body, user }),
    onSuccess: (saved) => {
      setName('');
      setFrom('');
      setTo('');
      queryClient.setQueryData(periodsKey(sheet), saved);
    },
  });
  // Close a period, or reopen a closed one (a steward only).
  const act = useMutation({
    mutationFn: ({ name, action }: { name: string; action: 'close' | 'reopen' }) =>
      postJson<Period[]>(
        `/api/sheets/${encodeURIComponent(sheet)}/periods/${encodeURIComponent(name)}/${action}`,
        { user },
      ),
    onSuccess: (saved) => queryClient.setQueryData(periodsKey(sheet), saved),
  });
  const personOf = new Map(people.map((p) => [p.id, p]));
  const heldOf = new Map(people.map((p) => [p.id, p.held]));
  const dueTotalOf = (period: Period) =>
    period.closed ? toCents(period.closedTotal) : claims
      .filter((c) => personOf.has(c.personId) && countsLive(c, heldOf.get(c.personId)!) && periodOf(periods, c.date) === period)
      .reduce((sum, c) => sum + (claimDue(c, rateOn(rates, gradeOn(personOf.get(c.personId)!, c.date), c.date), floor, late) ?? 0n), 0n);
  return (
    <>
      <table data-testid="periods">
        <thead>
          <tr>
            <th>Period</th>
            <th>From</th>
            <th>To</th>
            <th>Due</th>
            <th>Closed</th>
            <th></th>
          </tr>
        </thead>
        <tbody>
          {periods.map((p) => (
            <tr key={p.name} data-testid={`period-row-${p.name}`}>
              <td data-testid="period-name">{p.name}</td>
              <td data-testid="period-from">{p.from}</td>
              <td data-testid="period-to">{p.to}</td>
              <td data-testid="period-due-total">{formatCents(dueTotalOf(p))}</td>
              <td data-testid="period-closed">{p.closed ? 'yes' : 'no'}</td>
              <td>
                {!p.closed && (
                  <button
                    type="button"
                    data-testid="period-close"
                    onClick={() => {
                      act.reset();
                      act.mutate({ name: p.name, action: 'close' });
                    }}
                  >
                    Close
                  </button>
                )}{' '}
                <button
                  type="button"
                  data-testid="period-reopen"
                  onClick={() => {
                    act.reset();
                    act.mutate({ name: p.name, action: 'reopen' });
                  }}
                >
                  Reopen
                </button>
                {act.isError && act.variables?.name === p.name && (
                  <span data-testid="period-error" role="alert">
                    {act.variables.action === 'reopen'
                      ? ' Could not reopen the period: only a steward can reopen it, and only while it is closed.'
                      : ' Could not close the period.'}
                  </span>
                )}
              </td>
            </tr>
          ))}
        </tbody>
      </table>
      <form
        data-testid="period-form"
        onSubmit={(e) => {
          e.preventDefault();
          submitOnce(() => {
            add.reset();
            return add.mutateAsync({ name: name.trim(), from: from.trim(), to: to.trim() });
          });
        }}
      >
        <input
          data-testid="period-form-name"
          value={name}
          placeholder="Period name"
          onChange={(e) => {
            setName(e.target.value);
            add.reset();
          }}
        />{' '}
        <input
          data-testid="period-form-from"
          value={from}
          placeholder="From (YYYY-MM-DD)"
          onChange={(e) => {
            setFrom(e.target.value);
            add.reset();
          }}
        />{' '}
        <input
          data-testid="period-form-to"
          value={to}
          placeholder="To (YYYY-MM-DD)"
          onChange={(e) => {
            setTo(e.target.value);
            add.reset();
          }}
        />{' '}
        <button type="submit" data-testid="period-form-submit">Add period</button>
        {add.isError && <span data-testid="period-form-error" role="alert"> Could not add the period: it needs a name not already on the sheet and a from-date on or before its to-date (YYYY-MM-DD), not overlapping another period.</span>}
      </form>
    </>
  );
}
import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';

/** `version` goes up on every save; an editor sends back the version it loaded, so a save over
 *  someone else's newer one is refused. `statementCount` is how many statements were taken;
 *  `statedTotal` is the last one's due-total ("n/a" possible, "" when none) and `statementDate` the
 *  sheet's today when it was taken ("" when none). `retired` is whether a retirement date is set
 *  (retired at once, whatever the date) and `retiredFrom` is that date ("" when none). `held` is
 *  whether the person is on hold: their OPEN claims then count in no live total. `patrons` are the
 *  names of the people they named as patrons, sorted, and `patronIds` those people's ids. `grade`
 *  is the grade in force on the sheet's today when loaded and `grades` every grade recorded. */
export type Person = {
  id: string;
  name: string;
  grade: string;
  version: number;
  statementCount: number;
  statedTotal: string;
  statementDate: string;
  retired: boolean;
  retiredFrom: string;
  held: boolean;
  patrons: string[];
  patronIds: string[];
  grades: GradeFrom[];
};

/** A grade in force from a date (YYYY-MM-DD; "" for the beginning of time). */
export type GradeFrom = { from: string; grade: string };

/** The person's grade in force on a date: the one with the latest from-date on or before it (with
 *  no date yet, the one in force on the sheet's today as loaded). */
export function gradeOn(person: Person, date: string | undefined): string {
  if (date === undefined) return person.grade;
  let found: GradeFrom | undefined;
  for (const g of person.grades) {
    if (g.from <= date && (found === undefined || g.from >= found.from)) found = g;
  }
  return found?.grade ?? person.grade;
}

export const GRADES = ['A', 'B', 'C'] as const;

export const peopleKey = (sheet: string) => ['sheet', sheet, 'people'] as const;

/** The sheet's people, in the order they were added. */
export function usePeople(sheet: string): Person[] {
  const { data } = useQuery({
    queryKey: peopleKey(sheet),
    queryFn: () => getJson<Person[]>(`/api/sheets/${encodeURIComponent(sheet)}/people`),
    enabled: sheet !== '',
  });
  return data ?? [];
}
import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';

export type ClaimStatus = 'DRAFT' | 'OPEN' | 'SETTLED' | 'VOID';

/** A claim; `amount` is shown with two decimals ("10.25"); `number` is the one given when it was
 *  opened (a voided claim keeps it), "" for a draft; `due` is the due fixed when it was settled, else the
 *  figure the person's last statement bound it to, "" while its due is live (worked from the current
 *  rate) or bound to n/a; `stated` is whether the last statement bound it. A claim with a negative
 *  amount is a correction: its due has no floor and no late charge. */
export type Claim = {
  id: string;
  personId: string;
  amount: string;
  date: string;
  note: string;
  status: ClaimStatus;
  number: string;
  due: string;
  /** The user who opened the claim, "" if it was never opened. */
  openedBy: string;
  stated: boolean;
  /** The number of the SETTLED claim a correction (a negative amount) corrects, "" for any other claim. */
  corrects: string;
};

/** Only OPEN and SETTLED claims count toward claimed, due-total and every total. */
export const counts = (c: Claim) => c.status === 'OPEN' || c.status === 'SETTLED';

/** Whether a claim counts in the live totals: it counts, and is not OPEN while its person is held. */
export const countsLive = (c: Claim, held: boolean) => counts(c) && !(held && c.status === 'OPEN');

export const claimsKey = (sheet: string) => ['sheet', sheet, 'claims'] as const;

/** The sheet's claims, newest first. */
export function useClaims(sheet: string): Claim[] {
  const { data } = useQuery({
    queryKey: claimsKey(sheet),
    queryFn: () => getJson<Claim[]>(`/api/sheets/${encodeURIComponent(sheet)}/claims`),
    enabled: sheet !== '',
  });
  return data ?? [];
}

/** The amounts of the claims that count added up, shown with two decimals. Summed in whole cents
 *  so no float drift shows. */
export function sumAmounts(claims: Claim[]): string {
  const cents = claims.filter(counts).reduce((sum, c) => sum + Math.round(Number(c.amount) * 100), 0);
  return (cents / 100).toFixed(2);
}

